  "overview": {
    "short": "KISCO홀딩스는 한국철강·환영철강공업 등 철강 계열사를 지배하는 지주회사",
    "summary": "KISCO홀딩스는 한국철강·환영철강공업 등 철강 계열사를 지배하는 지주회사입니다. 연결 주력 사업은 건설에 쓰는 철근 등 철강제품의 생산·판매입니다.",
    "takeaways": [
      "KISCO홀딩스는 한국철강·환영철강공업 등 철강 계열사를 지배하는 지주회사입니다.",
      "연결 주력 사업은 건설에 쓰는 철근 등 철강제품의 생산·판매입니다.",
      "지주회사 자체의 배당·관리 수익과 철강 제조 자회사 실적은 서로 다른 범위입니다.",
      "계열사의 부동산 임대와 섬유 판매 등 다른 사업도 연결에 포함됩니다.",
      "한국철강과는 별도 종목이지만 연결 실적이 겹치므로 두 회사 매출을 더해서 보지 않습니다."
    ],
    "business": [
      {
        "name": "철강 제조",
        "desc": "한국철강·환영철강공업 등을 통해 철근 등 건설용 철강제품을 생산·판매합니다."
      },
      {
        "name": "계열사 관리",
        "desc": "계열사 투자와 경영관리 등을 수행하며 배당·용역 등 지주회사 자체 수익을 얻습니다."
      },
      {
        "name": "임대·섬유 판매",
        "desc": "대흥산업의 임대와 서륭의 섬유 판매 등 연결 범위의 다른 사업도 반영합니다."
      }
    ],
    "drivers": [
      {
        "title": "건설용 철강 수요",
        "desc": "건설 공사량과 철근 출하·판매가격이 제조 사업 실적에 영향을 줍니다."
      },
      {
        "title": "철스크랩과 전력",
        "desc": "철스크랩·전력 등 생산 비용을 제품 가격과 공장 가동률에 함께 연결해 봅니다."
      },
      {
        "title": "계열사 중복",
        "desc": "자회사 실적이 이미 연결에 포함됐는지 확인하고 상장 계열사 수치를 중복 합산하지 않습니다."
      }
    ],
